// 抖音官方图标（内置 base64，避免依赖文件系统/asar 路径，任何环境 100% 可用）
const DOUYIN_ICON = 'data:image/x-icon;base64,';

// pathbinding.js - 安装路径绑定模块
// 设置页只展示一个横条「安装路径绑定 → 去设置」，全部绑定流程（自动扫描、
// 手动编辑、浏览选择、实时校验）都在弹窗内完成；弹窗样式与「设置 - 使用说明」一致。
(function () {
  'use strict';

  // 分组定义：每组 = 软件名 + 图标候选 exe + 所属路径项（key/label/placeholder）
  // fixedIconPath：exe 提取的图标不正确时，直接使用指定的图标文件（例：抖音）
  const GROUPS = [
    {
      id: 'qq', name: 'QQ', exeCandidates: ['QQ.exe', 'QQScLauncher.exe'],
      iconFallback: '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z"/></svg>',
      items: [
        { key: 'qqInstallPath', label: '安装路径', placeholder: '如: C:\\Program Files\\Tencent\\QQNT' },
        { key: 'qqFileDir', label: '文件目录', placeholder: '如: C:\\Users\\xxx\\Documents\\Tencent Files' },
        { key: 'qqCacheDir', label: '缓存目录', placeholder: '自动发现后保存，或手动填写缓存目录' }
      ]
    },
    {
      id: 'wechat', name: '微信', exeCandidates: ['WeChat.exe', 'Weixin.exe', 'WeChatApp.exe'],
      iconFallback: '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M8.691 2.188C3.891 2.188 0 5.476 0 9.53c0 2.212 1.17 4.203 3.002 5.55a.59.59 0 0 1 .213.665l-.39 1.48c-.019.07-.048.141-.048.213 0 .163.13.295.29.295a.326.326 0 0 0 .167-.054l1.903-1.114a.864.864 0 0 1 .717-.098 10.16 10.16 0 0 0 2.837.403c.276 0 .543-.027.811-.05-.857-2.578.157-4.972 1.932-6.446 1.703-1.415 3.882-1.98 5.853-1.98H20.5V9.53c0-4.054-3.891-7.342-8.691-7.342zM5.785 5.542A1.093 1.093 0 1 1 5.79 7.726a1.093 1.093 0 0 1-.005-2.184zm8.257 0a1.093 1.093 0 1 1 .005 2.184 1.093 1.093 0 0 1-.005-2.184z"/></svg>',
      items: [
        { key: 'wechatInstallPath', label: '安装路径', placeholder: '如: C:\\Program Files\\Tencent\\WeChat' },
        { key: 'wechatFileDir', label: '文件目录', placeholder: '如: C:\\Users\\xxx\\Documents\\xwechat_files' },
        { key: 'wechatCacheDir', label: '缓存目录', placeholder: '自动发现后保存，或手动填写 temp / Cache 目录' }
      ]
    },
    {
      id: 'douyin', name: '抖音', exeCandidates: ['Douyin.exe', 'douyin.exe'],
      // 抖音安装目录中的 exe 图标不正确，直接使用内置 base64 官方图标（任何环境 100% 可用，不依赖文件系统）
      iconDataUrl: DOUYIN_ICON,
      iconFallback: '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M16.6 5.82A4.278 4.278 0 0 1 15.54 3h-3.09v12.4a2.592 2.592 0 0 1-2.59 2.5c-1.42 0-2.6-1.16-2.6-2.6 0-1.72 1.66-3.01 3.37-2.48V9.66c-3.45-.46-6.47 2.22-6.47 5.64 0 3.33 2.76 5.7 5.69 5.7 3.14 0 5.69-2.55 5.69-5.7V9.01a7.35 7.35 0 0 0 4.3 1.38V7.3a4.3 4.3 0 0 1-4.3-1.48z"/></svg>',
      items: [
        { key: 'douyinInstallPath', label: '安装路径', placeholder: '如: C:\\Users\\xxx\\AppData\\Local\\Douyin' },
        { key: 'douyinCacheDir', label: '缓存目录', placeholder: '自动发现后保存，或手动填写缓存目录' }
      ]
    },
    {
      id: 'netease', name: '网易云音乐', exeCandidates: ['cloudmusic.exe', 'CloudMusic.exe'],
      iconFallback: '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 3v10.55A4 4 0 1 0 14 17V7h4V3h-6zM4 17a4 4 0 1 0 2 3.46A4 4 0 0 0 4 17z"/></svg>',
      items: [
        { key: 'neteaseMusicInstallPath', label: '安装路径', placeholder: '如: C:\\Program Files\\CloudMusic' },
        { key: 'neteaseCacheDir', label: '缓存目录', placeholder: '自动发现后保存，或手动填写缓存目录' }
      ]
    }
  ];

  const ALL_KEYS = GROUPS.flatMap(g => g.items.map(i => i.key));
  const FIRST_LAUNCH_KEY = 'winclean-paths-first-launch-done';

  let pathConfig = {};
  let icons = {};        // groupId -> dataUrl
  let isInitialized = false;
  let modal = null;      // { ctrl, backdrop, body, hint }

  function escapeAttr(s) {
    return String(s || '').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  function getLabel(key) {
    for (const group of GROUPS) {
      const item = group.items.find(i => i.key === key);
      if (item) return `${group.name}${item.label}`;
    }
    return key;
  }

  function groupOf(key) {
    return GROUPS.find(g => g.items.some(i => i.key === key)) || null;
  }

  // ==================== 图标 ====================
  async function loadIcons() {
    if (!window.api?.paths) return;
    for (const group of GROUPS) {
      // 内置 base64 图标（抖音）：直接使用，跳过一切文件系统/IPC 依赖
      if (group.iconDataUrl) { icons[group.id] = group.iconDataUrl; continue; }
      // 固定图标路径（exe 图标不正确时的兜底方案）
      if (group.fixedIconPath && window.api.paths.fileIcon) {
        try {
          const resp = await window.api.paths.fileIcon(group.fixedIconPath);
          if (resp && resp.success && resp.dataUrl) { icons[group.id] = resp.dataUrl; continue; }
        } catch (e) { /* 固定图标不可用则继续尝试 exe 提取 */ }
      }
      const installPath = pathConfig[group.items[0].key] || '';
      if (!installPath || !window.api.paths.appIcon) continue;
      try {
        const resp = await window.api.paths.appIcon(installPath, group.exeCandidates);
        if (resp && resp.success && resp.dataUrl) icons[group.id] = resp.dataUrl;
      } catch (e) { /* 图标提取失败使用占位图标 */ }
    }
  }

  async function refreshGroupIcon(groupId) {
    const group = GROUPS.find(g => g.id === groupId);
    if (!group || !modal) return;
    // 内置 base64 图标直接设置
    if (group.iconDataUrl) { icons[groupId] = group.iconDataUrl; }
    else if (group.fixedIconPath && window.api?.paths?.fileIcon) {
      try {
        const resp = await window.api.paths.fileIcon(group.fixedIconPath);
        if (resp && resp.success && resp.dataUrl) { icons[groupId] = resp.dataUrl; }
      } catch (e) { /* 忽略 */ }
    }
    const img = modal.body.querySelector(`[data-group="${groupId}"] .pw-group-ico img`);
    const ico = modal.body.querySelector(`[data-group="${groupId}"] .pw-group-ico`);
    if (!ico) return;
    if (icons[groupId]) {
      if (img) img.src = icons[groupId];
      else ico.innerHTML = `<img src="${icons[groupId]}" alt="${escapeAttr(group.name)}" />`;
    }
  }

  function groupIconHtml(group) {
    if (icons[group.id]) return `<img src="${escapeAttr(icons[group.id])}" alt="${escapeAttr(group.name)}" />`;
    return group.iconFallback;
  }

  // ==================== 弹窗渲染 ====================
  function renderBody() {
    if (!modal) return;
    modal.body.innerHTML = GROUPS.map(group => {
      const itemsHtml = group.items.map(item => {
        const value = pathConfig[item.key] || '';
        let hint = '', hintCls = '';
        if (!value) { hint = '未绑定，可点击「浏览」选择或手动填写'; hintCls = ''; }
        else if (value && value.startsWith('!')) { hint = '路径不存在，请检查'; hintCls = 'warn'; }
        return `
          <div class="pw-item" data-key="${escapeAttr(item.key)}">
            <span class="pw-item-label">${escapeAttr(item.label)}</span>
            <div class="pw-item-input">
              <input type="text" class="field-input pw-input" data-key="${escapeAttr(item.key)}"
                     value="${escapeAttr(value)}" placeholder="${escapeAttr(item.placeholder)}" spellcheck="false" />
              <div class="pw-hint ${hintCls}" data-hint="${escapeAttr(item.key)}">${escapeAttr(hint)}</div>
            </div>
            <button class="btn btn-secondary btn-small pw-browse" data-key="${escapeAttr(item.key)}" data-tip="浏览选择文件夹">浏览</button>
          </div>`;
      }).join('');
      return `
        <section class="pw-group" data-group="${escapeAttr(group.id)}">
          <div class="pw-group-head">
            <span class="pw-group-ico">${groupIconHtml(group)}</span>
            <span class="pw-group-title">${escapeAttr(group.name)}</span>
            <span class="pw-group-meta">${group.items.length} 项路径</span>
          </div>
          <div class="pw-items">${itemsHtml}</div>
        </section>`;
    }).join('');
    bindBodyEvents();
  }

  function bindBodyEvents() {
    if (!modal) return;
    modal.body.querySelectorAll('.pw-input').forEach(input => {
      const commit = () => savePath(input.dataset.key, input.value.trim());
      input.addEventListener('change', commit);
      input.addEventListener('blur', () => {
        if (input.value.trim() !== (pathConfig[input.dataset.key] || '')) commit();
      });
    });
    modal.body.querySelectorAll('.pw-browse').forEach(btn => {
      btn.addEventListener('click', () => browsePath(btn.dataset.key));
    });
  }

  function setHint(key, text, cls) {
    if (!modal) return;
    const el = modal.body.querySelector(`[data-hint="${key}"]`);
    if (!el) return;
    el.textContent = text || '';
    el.className = 'pw-hint' + (cls ? ' ' + cls : '');
  }

  // ==================== 数据读写 ====================
  async function savePath(key, value) {
    if (!window.api?.paths) return;
    try {
      const resp = await window.api.paths.save(key, value);
      if (resp && resp.success) {
        pathConfig[key] = value;
        if (!value) { setHint(key, '未绑定，可点击「浏览」选择或手动填写', ''); }
        else if (!resp.exists) { setHint(key, '路径不存在，请检查', 'warn'); window.app?.toast('warning', `${getLabel(key)} 路径不存在，请检查`); }
        else { setHint(key, '已保存', 'ok'); }
        const group = groupOf(key);
        if (group && group.items[0].key === key) {
          icons[group.id] = null;
          await refreshGroupIcon(group.id);
        }
      } else {
        // 审查 SET-1（2026-09-15）：原实现无失败分支 → 主进程拒绝（白名单未收录 / 落盘失败）
        // 时界面无任何反馈，用户误以为「已保存」。这里显式回滚提示，避免输入静默丢失。
        setHint(key, '保存失败，请重试', 'warn');
        window.app?.toast('error', `保存失败：${resp?.message || '路径配置无效'}`);
      }
    } catch (e) {
      window.app?.toast('error', '保存失败: ' + e.message);
    }
  }

  async function browsePath(key) {
    if (!window.api?.paths) return;
    try {
      const resp = await window.api.paths.browse(getLabel(key), pathConfig[key] || '');
      if (resp && resp.success && resp.path) {
        const input = modal?.body.querySelector(`.pw-input[data-key="${key}"]`);
        if (input) input.value = resp.path;
        await savePath(key, resp.path);
      }
    } catch (e) {
      window.app?.toast('error', '浏览失败: ' + e.message);
    }
  }

  async function autoScan(silent) {
    if (!window.api?.paths) return 0;
    try {
      writeLog('info', '开始自动扫描安装路径');
      const resp = await window.api.paths.scan();
      if (resp && resp.success && resp.data) {
        let found = 0;
        for (const item of ALL_KEYS) {
          const scanned = resp.data[item] || '';
          if (scanned && !pathConfig[item]) {
            pathConfig[item] = scanned;
            await window.api.paths.save(item, scanned);
            found++;
          }
        }
        if (resp.data.scannedAt) {
          pathConfig.scannedAt = resp.data.scannedAt;
          await window.api.paths.save('scannedAt', resp.data.scannedAt);
        }
        await loadIcons();
        renderBody();
        updateFooter();
        if (!silent) {
          if (found > 0) window.app?.toast('success', `安装路径扫描完成，已自动绑定 ${found} 项`);
          else window.app?.toast('info', '安装路径扫描完成，部分路径未识别，请手动填写');
        }
        return found;
      }
    } catch (e) {
      window.app?.toast('error', '路径扫描失败: ' + e.message);
    }
    return 0;
  }

  function updateFooter() {
    if (!modal) return;
    const at = pathConfig.scannedAt ? new Date(pathConfig.scannedAt).toLocaleString('zh-CN') : '';
    modal.hint.textContent = at ? `上次扫描：${at}` : '尚未扫描，可点击「重新扫描」自动识别';
  }

  // ==================== 弹窗开关 ====================
  // v3.2.0 弹窗统一批次：骨架改由 modal.js 工厂生成（Esc/遮罩/× 关闭 + 焦点陷阱统一）
  function openModal() {
    closeModal();
    const ctrl = window.modal.create({
      id: 'pathBindingBackdrop',
      title: '安装路径绑定',
      backdropClass: 'path-binding-backdrop',
      modalClass: 'path-binding-modal',
      bodyClass: 'pw-body path-binding-body',
      bodyHtml: '<div class="pw-empty">正在加载路径配置…</div>',
      footerClass: 'pw-footer',
      footerHtml: `
          <span class="pw-last-scan" data-role="hint"></span>
          <span class="model-picker-spacer"></span>
          <button class="btn btn-secondary" data-role="scanBtn" type="button">重新扫描</button>
          <button class="btn btn-primary" data-role="doneBtn" type="button">完成</button>`
    });
    modal = {
      ctrl,
      backdrop: ctrl.backdrop,
      body: ctrl.body,
      hint: ctrl.backdrop.querySelector('[data-role="hint"]')
    };

    ctrl.backdrop.querySelector('[data-role="doneBtn"]').addEventListener('click', closeModal);
    ctrl.backdrop.querySelector('[data-role="scanBtn"]').addEventListener('click', async e => {
      const btn = e.currentTarget;
      btn.disabled = true;
      btn.textContent = '扫描中…';
      try { await autoScan(false); } finally { btn.disabled = false; btn.textContent = '重新扫描'; }
    });

    // 先渲染已保存配置，再后台补齐图标，避免等待图标造成白屏
    renderBody();
    updateFooter();
    loadIcons().then(() => renderBody());
  }

  function closeModal() {
    if (modal) { modal.ctrl.close(); modal = null; }
  }

  async function load() {
    if (!window.api?.paths) return;
    try {
      const resp = await window.api.paths.load();
      if (resp && resp.success && resp.data) pathConfig = resp.data || {};
    } catch (e) {
      console.error('加载路径配置失败:', e);
    }

    // 首次启动自动扫描（仅在后台静默补全，不弹窗打扰）
    let firstLaunchDone = false;
    try { firstLaunchDone = localStorage.getItem(FIRST_LAUNCH_KEY) === 'true'; } catch (e) {}
    if (!firstLaunchDone) {
      try { localStorage.setItem(FIRST_LAUNCH_KEY, 'true'); } catch (e) {}
      setTimeout(() => { autoScan(true); }, 1500);
    }
  }

  function writeLog(level, message) {
    if (window.app?.log) window.app.log(level, message);
  }

  // ==================== 外观设置（强调色 / 背景图片 / 系统信息折叠） ====================
  const APPEARANCE_KEY = 'winclean-appearance';

  function escapeHtml(text) {
    const map = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' };
    return String(text == null ? '' : text).replace(/[&<>"']/g, m => map[m]);
  }

  function loadAppearance() {
    try {
      const v = JSON.parse(localStorage.getItem(APPEARANCE_KEY) || '{}');
      return v && typeof v === 'object' ? v : {};
    } catch (e) { return {}; }
  }
  function saveAppearance(v) {
    try { localStorage.setItem(APPEARANCE_KEY, JSON.stringify(v)); } catch (e) {}
  }

  // 应用强调色：写入 CSS 变量（按钮 / 高亮 / 选中态即时生效）
  function applyAccent(color) {
    const root = document.documentElement;
    if (color) {
      // 前景文字色按 WCAG 相对亮度自动选定；交互态与 soft/glow 同步派生，
      // 避免自定义色只影响按钮底色，其他高亮仍停留在默认薰衣草色。
      root.style.setProperty('--accent', color);
      root.style.setProperty('--accent-hover', `color-mix(in srgb, ${color} 82%, white)`);
      root.style.setProperty('--accent-press', `color-mix(in srgb, ${color} 82%, black)`);
      root.style.setProperty('--accent-light', `color-mix(in srgb, ${color} 16%, transparent)`);
      root.style.setProperty('--accent-soft', `color-mix(in srgb, ${color} 16%, transparent)`);
      root.style.setProperty('--accent-glow', `color-mix(in srgb, ${color} 32%, transparent)`);
      root.style.setProperty('--border-accent', color);
      root.style.setProperty('--accent-text', readableAccentText(color));
    } else {
      for (const name of ['--accent', '--accent-hover', '--accent-press', '--accent-light', '--accent-soft', '--accent-glow', '--border-accent', '--accent-text']) {
        root.style.removeProperty(name);
      }
    }
  }

  // 按相对亮度（WCAG L 公式）判定 accent 实底上的可读前景色
  function readableAccentText(hex) {
    const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || '').trim());
    if (!m) return '#FFFFFF';
    const n = parseInt(m[1], 16);
    const ch = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map(v => {
      const s = v / 255;
      return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
    });
    const lum = 0.2126 * ch[0] + 0.7152 * ch[1] + 0.0722 * ch[2];
    // 与白/黑文字对比度取更优者（阈值 0.35 介于白 5:1 与黑 5:1 的交点附近）
    return lum > 0.35 ? '#23244E' : '#FFFFFF';
  }

  // 应用背景图片：body::before 水印式铺底（置于内容之上、弹窗之下）。
  // 批次：雾化度语义反转 —— 入参 opacity 现为「雾化度」（0=零效果纯展示图片，100=雾化效果100%），
  // 图片不透明度 = (100 - 雾化度)/100；旧语义（值=图片不透明度）已在读取侧一次性迁移。
  // 批次：背景视角可调 —— posX/posY 为 0-100 的裁切窗口位置百分比（cover 下只对图片超出
  // 窗口的那根轴生效），不传回落 50/50（居中，与旧行为一致）。
  function applyBackground(file, opacity, posX, posY) {
    const root = document.documentElement;
    if (file) {
      const url = file.startsWith('file:') ? file : 'file:///' + String(file).replace(/\\/g, '/').replace(/^\//, '');
      root.style.setProperty('--app-bg-image', `url("${url}")`);
      const fog = opacity == null ? 85 : opacity;
      root.style.setProperty('--app-bg-opacity', String((100 - fog) / 100));
      const px = clampPercent(posX, 50);
      const py = clampPercent(posY, 50);
      root.style.setProperty('--app-bg-position', `${px}% ${py}%`);
      document.body.classList.add('bg-image-on');
    } else {
      root.style.removeProperty('--app-bg-image');
      root.style.removeProperty('--app-bg-opacity');
      root.style.removeProperty('--app-bg-position');
      document.body.classList.remove('bg-image-on');
    }
  }

  // 百分比参数钳位：非数值/越界一律收敛到 0-100，异常时取 fallback
  function clampPercent(v, fallback) {
    const n = Number(v);
    if (!Number.isFinite(n)) return fallback;
    return Math.max(0, Math.min(100, Math.round(n)));
  }

  // 批次（v3.0）：背景图切换淡入淡出 —— 先把对应背景层透明度淡到 0，换图后再淡回。
  // fadeVar：预设层 --preset-bg-fade / 导入层 --app-bg-fade（main.css 乘进 opacity）。
  // reduce-motion 直接应用（无动画红线）；淡出仍在途时立即换图并淡入，避免连续切换排队卡顿。
  const BG_FADE_MS = 340; // 与 --duration-slow(320ms) 同步，留少量余量
  function crossfadeBg(fadeVar, applyFn) {
    const root = document.documentElement;
    let reduced = false;
    try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) {}
    if (reduced) { applyFn(); return; }
    if (root.style.getPropertyValue(fadeVar) === '0') {
      applyFn();
      root.style.setProperty(fadeVar, '1');
      return;
    }
    root.style.setProperty(fadeVar, '0');
    setTimeout(() => {
      applyFn();
      void document.body.offsetWidth; // 强制样式重算：新图先以零透明度渲染，再开始淡入
      root.style.setProperty(fadeVar, '1');
    }, BG_FADE_MS);
  }

  // 批次：雾化度语义反转迁移 —— 旧值存的是「图片不透明度」（100=纯图），新值为「雾化强度」
  // （0=纯图，100=全雾）。一次性换算 100-v（迁移前后视觉效果一致）并打 bgOpacityFog 标记防重复。
  function migrateBgOpacityToFog(ap) {
    if (ap.bgOpacityFog === true) return ap;
    if (ap.bgOpacity != null) ap.bgOpacity = 100 - ap.bgOpacity;
    ap.bgOpacityFog = true;
    saveAppearance(ap);
    return ap;
  }

  function renderBgList(ap) {
    const listEl = document.getElementById('bgList');
    const bodyEl = document.getElementById('bgListBody');
    const currentRow = document.getElementById('bgCurrentRow');
    const thumb = document.getElementById('bgThumb');
    if (!listEl || !bodyEl) return;
    window.api?.appearance?.listBg?.().then(resp => {
      const files = (resp && resp.success && resp.data) || [];
      const head = listEl.querySelector('.bg-list-head');
      if (head) head.firstChild && (head.firstChild.textContent = `已导入的图片（${files.length}）`);
      if (!files.length) {
        listEl.style.display = 'none';
        bodyEl.innerHTML = '';
        return;
      }
      listEl.style.display = 'block';
      bodyEl.innerHTML = files.map(f => `
        <div class="bg-list-item${ap.bgPath === f.path ? ' active' : ''}" data-file="${escapeHtml(f.path)}" data-tip="点击设为背景">
          <span class="bg-list-name">${escapeHtml(f.name)}</span>
          <button class="bg-list-del" data-file="${escapeHtml(f.path)}" data-tip="删除此图片">✕</button>
        </div>
      `).join('');
      bodyEl.querySelectorAll('.bg-list-item').forEach(el => {
        el.addEventListener('click', (e) => {
          if (e.target.closest('.bg-list-del')) return;
          const file = el.dataset.file;
          const ap2 = loadAppearance();
          ap2.bgPath = file;
          saveAppearance(ap2);
          crossfadeBg('--app-bg-fade', () => applyBackground(file, ap2.bgOpacity, ap2.bgPosX, ap2.bgPosY));
          refreshBgCurrent(ap2);
          renderBgList(ap2);
        });
      });
      bodyEl.querySelectorAll('.bg-list-del').forEach(btn => {
        btn.addEventListener('click', async (e) => {
          e.stopPropagation();
          const file = btn.dataset.file;
          await window.api?.appearance?.deleteBg?.(file);
          const ap2 = loadAppearance();
          if (ap2.bgPath === file) {
            delete ap2.bgPath;
            saveAppearance(ap2);
            crossfadeBg('--app-bg-fade', () => applyBackground(null));
            refreshBgCurrent(ap2);
          }
          renderBgList(ap2);
        });
      });
    });
    if (currentRow) currentRow.style.display = ap.bgPath ? 'flex' : 'none';
    if (thumb && ap.bgPath) thumb.src = 'file:///' + String(ap.bgPath).replace(/\\/g, '/').replace(/^\//, '');
  }

  function refreshBgCurrent(ap) {
    const currentRow = document.getElementById('bgCurrentRow');
    const thumb = document.getElementById('bgThumb');
    const slider = document.getElementById('bgOpacity');
    const val = document.getElementById('bgOpacityVal');
    // 批次：背景视角可调 —— 视角滑块与重置按钮跟「已选图片」同进退
    const viewRow = document.getElementById('bgViewRow');
    const posXSlider = document.getElementById('bgPosX');
    const posYSlider = document.getElementById('bgPosY');
    const posXVal = document.getElementById('bgPosXVal');
    const posYVal = document.getElementById('bgPosYVal');
    if (currentRow) currentRow.style.display = ap.bgPath ? 'flex' : 'none';
    if (viewRow) viewRow.style.display = ap.bgPath ? 'flex' : 'none';
    if (thumb && ap.bgPath) thumb.src = 'file:///' + String(ap.bgPath).replace(/\\/g, '/').replace(/^\//, '');
    if (slider) {
      slider.value = ap.bgOpacity == null ? 85 : ap.bgOpacity;
      // 编程式赋值不触发 input 事件，手动同步轨道填充（ds.slider）
      window.ds?.slider?.sync?.(slider);
    }
    if (val) val.textContent = (ap.bgOpacity == null ? 85 : ap.bgOpacity) + '%';
    // 视角滑块同步存储值（缺省 50 = 居中），同样手动同步轨道填充
    const px = ap.bgPosX == null ? 50 : ap.bgPosX;
    const py = ap.bgPosY == null ? 50 : ap.bgPosY;
    if (posXSlider) {
      posXSlider.value = px;
      window.ds?.slider?.sync?.(posXSlider);
    }
    if (posYSlider) {
      posYSlider.value = py;
      window.ds?.slider?.sync?.(posYSlider);
    }
    if (posXVal) posXVal.textContent = px + '%';
    if (posYVal) posYVal.textContent = py + '%';
  }

  function initAppearance() {
    // 批次：雾化度语义反转 —— 皮肤键迁移后接着做雾化度一次性迁移（localStorage 侧）
    const ap = migrateBgOpacityToFog(migrateSkinToBlur(loadAppearance()));

    // 系统信息折叠（默认折叠，点击展开）
    const sec = document.getElementById('systemInfoSection');
    const chevron = document.getElementById('systemInfoChevron');
    try {
      if (localStorage.getItem('winclean-systeminfo-open') === '1' && sec) sec.classList.remove('collapsed');
    } catch (e) {}
    if (sec && !sec.classList.contains('collapsed') && chevron) chevron.textContent = '▴';
    document.getElementById('systemInfoToggle')?.addEventListener('click', () => {
      if (!sec) return;
      const open = sec.classList.toggle('collapsed') === false;
      if (chevron) chevron.textContent = open ? '▴' : '▾';
      try { localStorage.setItem('winclean-systeminfo-open', open ? '1' : '0'); } catch (e) {}
    });
    // 阶段三：折叠区补齐 ARIA（不改视觉逻辑，ds.accordion 只同步 aria-expanded/hidden）
    if (sec) window.ds?.accordion?.enhance(document.getElementById('systemInfoToggle'), sec);

    // 窗口材质五卡片：点击切换 + 高亮 + IPC 应用（即时生效并持久化）
    const materialCards = document.querySelectorAll('.material-card');
    function refreshMaterialCards(current) {
      materialCards.forEach(c => c.classList.toggle('selected', c.dataset.material === current));
    }
    // 材质总开关（窗口界面升级3，Motion.Lab toggle-flip 滑动开关）：
    // 关闭 = 各窗口即按「无材质」观感回落不透明；所选材质保留，重开即恢复
    const materialMaster = document.getElementById('materialMasterToggle');
    let materialOn = true;
    function syncMaterialMaster(on) {
      materialMaster?.classList.toggle('on', on);
      materialMaster?.setAttribute('aria-checked', on ? 'true' : 'false');
      materialMaster?.closest('.appearance-card')?.classList.toggle('material-off', !on);
    }
    materialMaster?.addEventListener('click', async () => {
      const next = !materialOn;
      materialOn = next;
      syncMaterialMaster(next);
      try {
        const resp = await window.api?.appearance?.setMaterialEnabled?.(next);
        if (resp && resp.success) {
          if (resp.material) document.body.dataset.material = resp.material;
          // 审查 2-4：material/materialEnabled 单一真源 = appearance.json（主进程持久化），
          // 不再镜像写入 localStorage（原双写导致两套存储可能漂移）
          window.app?.toast('success', next ? '窗口材质已开启' : '窗口材质已关闭（所选材质已记忆）');
        } else {
          materialOn = !next;
          syncMaterialMaster(materialOn);
          window.app?.toast('error', (resp && resp.message) || '材质开关切换失败');
        }
      } catch (e) {
        materialOn = !next;
        syncMaterialMaster(materialOn);
        window.app?.toast('error', '材质开关切换失败：' + e.message);
      }
    });
    materialMaster?.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); materialMaster.click(); }
    });
    // 初始高亮以主进程持久化值为准（窗口实际材质），避免与 localStorage 不一致
    // 导致「选中项和窗口效果对不上」。取不到时回退 mica（与主进程默认一致）。
    (async () => {
      let current = 'mica-alt';
      try {
        const resp = await window.api?.appearance?.getMaterial?.();
        if (resp && resp.material) current = resp.material;
        materialOn = resp ? resp.materialEnabled !== false : true;
      } catch (e) {}
      // 「无材质」卡片已移除（设置页整合4）：存储值为 none 时与总开关关闭等价，按关闭态展示；
      // 不回写主进程，用户重开总开关或点选任一材质卡后自然覆盖
      if (current === 'none' && materialOn) materialOn = false;
      refreshMaterialCards(current);
      syncMaterialMaster(materialOn);
    })();
    // 主进程材质广播：所有窗口（含本窗）统一跟随，body[data-material] 实时驱动 CSS 分级
    // （广播载荷是「生效材质」：总开关关闭时为 'none'，此时卡片高亮保持用户所选值不变）
    window.api?.appearance?.onMaterialChanged?.((m) => {
      document.body.dataset.material = m;
      if (materialOn) refreshMaterialCards(m);
    });
    materialCards.forEach(card => {
      card.addEventListener('click', async () => {
        if (!materialOn) return; // 总开关关闭期间材质卡为暂停态
        const m = card.dataset.material;
        refreshMaterialCards(m);
        const resp = await window.api?.appearance?.setMaterial?.(m);
        if (resp && resp.success) {
          // 同步材质标识到 body，CSS 据此做材质差异化着色
          document.body.dataset.material = m;
          // 审查 2-4：material 单一真源 = appearance.json，不再镜像写入 localStorage
          window.app?.toast('success', '窗口材质已切换：' + card.querySelector('.material-name')?.textContent);
        } else {
          // 失败回滚到主进程记录的真实材质
          try {
            const cur = await window.api?.appearance?.getMaterial?.();
            refreshMaterialCards((cur && cur.material) || 'mica-alt');
          } catch (e) {
            refreshMaterialCards('mica-alt');
          }
          window.app?.toast('error', (resp && resp.message) || '材质切换失败');
        }
      });
    });

    // 强调色
    const accentInput = document.getElementById('accentColor');
    const accentReset = document.getElementById('btnAccentReset');
    if (ap.accent && accentInput) {
      accentInput.value = ap.accent;
      applyAccent(ap.accent);
    }
    accentInput?.addEventListener('input', () => {
      applyAccent(accentInput.value);
      const ap2 = loadAppearance();
      ap2.accent = accentInput.value;
      saveAppearance(ap2);
    });
    accentReset?.addEventListener('click', () => {
      applyAccent(null);
      const ap2 = loadAppearance();
      delete ap2.accent;
      saveAppearance(ap2);
      if (accentInput) accentInput.value = '#6A59C9';
      window.app?.toast('success', '已恢复默认强调色');
    });

    // 背景图片
    refreshBgCurrent(ap);
    renderBgList(ap);
    applyBackground(ap.bgPath, ap.bgOpacity, ap.bgPosX, ap.bgPosY);
    document.getElementById('btnBgImport')?.addEventListener('click', async () => {
      const resp = await window.api?.appearance?.importBg?.();
      if (!resp || resp.canceled) return;
      if (!resp.success) {
        window.app?.toast('error', (resp && resp.message) || '导入背景图片失败');
        return;
      }
      const ap2 = loadAppearance();
      ap2.bgPath = resp.data.path;
      if (ap2.bgOpacity == null) ap2.bgOpacity = 85;
      // 新图新视角：换图即把裁切窗口回到居中，避免沿用上一张的取景
      delete ap2.bgPosX;
      delete ap2.bgPosY;
      saveAppearance(ap2);
      crossfadeBg('--app-bg-fade', () => applyBackground(ap2.bgPath, ap2.bgOpacity, ap2.bgPosX, ap2.bgPosY));
      refreshBgCurrent(ap2);
      renderBgList(ap2);
      window.app?.toast('success', '背景图片已导入并应用');
    });
    document.getElementById('btnBgClear')?.addEventListener('click', () => {
      const ap2 = loadAppearance();
      delete ap2.bgPath;
      saveAppearance(ap2);
      crossfadeBg('--app-bg-fade', () => applyBackground(null));
      refreshBgCurrent(ap2);
      window.app?.toast('success', '已清除背景图片');
    });
    // 打开背景图片存放目录（需求：点击跳转本地 backgrounds 目录）
    document.getElementById('btnOpenBgDir')?.addEventListener('click', () => {
      window.api?.appearance?.openBgDir?.()
        .then(r => { if (r && !r.success) window.app?.toast('error', (r.message) || '无法打开背景目录'); })
        .catch(() => window.app?.toast('error', '无法打开背景目录'));
    });
    const opacitySlider = document.getElementById('bgOpacity');
    opacitySlider?.addEventListener('input', () => {
      const v = parseInt(opacitySlider.value, 10);
      const val = document.getElementById('bgOpacityVal');
      if (val) val.textContent = v + '%';
      const ap2 = loadAppearance();
      ap2.bgOpacity = v;
      saveAppearance(ap2);
      applyBackground(ap2.bgPath, v, ap2.bgPosX, ap2.bgPosY);
    });
    // 批次：背景视角可调 —— 水平/垂直位置滑块，拖动即时生效并持久化（0-100 裁切窗口百分比）
    function bindBgPosSlider(sliderId, valId, storeKey) {
      const el = document.getElementById(sliderId);
      el?.addEventListener('input', () => {
        const v = parseInt(el.value, 10);
        const val = document.getElementById(valId);
        if (val) val.textContent = v + '%';
        const ap2 = loadAppearance();
        ap2[storeKey] = v;
        saveAppearance(ap2);
        applyBackground(ap2.bgPath, ap2.bgOpacity, ap2.bgPosX, ap2.bgPosY);
      });
    }
    bindBgPosSlider('bgPosX', 'bgPosXVal', 'bgPosX');
    bindBgPosSlider('bgPosY', 'bgPosYVal', 'bgPosY');
    // 重置视角：回到居中（50/50），与默认行为一致
    document.getElementById('btnBgViewReset')?.addEventListener('click', () => {
      const ap2 = loadAppearance();
      ap2.bgPosX = 50;
      ap2.bgPosY = 50;
      saveAppearance(ap2);
      applyBackground(ap2.bgPath, ap2.bgOpacity, 50, 50);
      refreshBgCurrent(ap2);
    });
    // 已导入图片列表折叠
    document.getElementById('bgListToggle')?.addEventListener('click', () => {
      const body = document.getElementById('bgListBody');
      const chev = document.querySelector('#bgListToggle .bg-list-chevron');
      if (!body) return;
      const open = body.style.display !== 'none';
      body.style.display = open ? 'none' : 'block';
      if (chev) chev.textContent = open ? '⌄' : '⌃';
    });
    window.ds?.accordion?.enhance(
      document.getElementById('bgListToggle'),
      document.getElementById('bgListBody')
    );

    // ---- UI 设计系统：背景模糊度 + 预设背景（设置页整合4） ----
    // 原「皮肤：经典/液态玻璃」二选一下拉与背景磨砂合并为 0-100% 无级「背景模糊度」滑块：
    // >0% = 液态玻璃面板，模糊半径按百分比线性缩放
    // （100% = 26px，与原液态玻璃一致；theme.js 启动期应用共用同一常量约定，改动需两处同步）。
    // v3.0 全局玻璃化：0% 仅表示「无磨砂」（移除 data-skin），容器表面仍为玻璃 alpha——
    // 表面 token 真源（main.css --surface-tint + 统一 alpha 表）本身就是玻璃值，无实心态。
    // 审查 5-5：上限常量收敛到 window.ds（theme.js 同源读取），ds 未加载时退回同值兜底
    const GLASS_MAX_BLUR_PX = window.ds?.GLASS_MAX_BLUR_PX || 26;
    function applyBgBlur(pct) {
      const v = Math.max(0, Math.min(100, Math.round(Number(pct) || 0)));
      if (v > 0) {
        document.body.dataset.skin = 'glass';
        document.documentElement.style.setProperty('--glass-blur', ((v / 100) * GLASS_MAX_BLUR_PX).toFixed(1) + 'px');
      } else {
        delete document.body.dataset.skin;
        document.documentElement.style.removeProperty('--glass-blur');
      }
    }
    // 旧值迁移：仅存有 skin 键的历史配置按 glass=100% / classic=0% 折算为 bgBlur
    function migrateSkinToBlur(stored) {
      if (stored.bgBlur == null) {
        stored.bgBlur = stored.skin === 'glass' ? 100 : 0;
        delete stored.skin;
        saveAppearance(stored);
      }
      return stored;
    }
    // applyPresetBg：body[data-preset-bg="graphite|wp-*"] 设置底层渐变/实拍墙纸
    // v3.2.0：白名单校验——已下架预设（aurora/sunset/wp-mountain）残留旧值时静默回落「无」，
    // 避免 body 挂着无 CSS 定义的 data-preset-bg 造成空白覆盖层
    const PRESET_BG_VALID = ['graphite', 'wp-winter', 'wp-gaming', 'wp-anime', 'wp-doll'];
    function applyPresetBg(preset) {
      const v = PRESET_BG_VALID.includes(preset) ? preset : '';
      if (v) document.body.dataset.presetBg = v;
      else delete document.body.dataset.presetBg;
    }
    const presetBgSelect = document.getElementById('presetBgSelect');
    if (presetBgSelect) presetBgSelect.value = ap.presetBg || '';
    applyPresetBg(ap.presetBg);
    presetBgSelect?.addEventListener('change', () => {
      const ap2 = loadAppearance();
      ap2.presetBg = presetBgSelect.value || '';
      saveAppearance(ap2);
      crossfadeBg('--preset-bg-fade', () => applyPresetBg(ap2.presetBg));
    });
    // ==================== 内置实拍壁纸轮换（v2.8.0） ====================
    // 仅 wp-* 实拍壁纸预设参与轮换（渐变/无背景时计时器空转）；默认 10s，可调/可关；
    // 窗口隐藏时自动暂停（visibilitychange），省电不打扰。状态存 winclean-appearance。
    // v3.2.0：预设壁纸下架「山峰 wp-mountain」（连同极光/落日渐变），WP_LIST 仅保留在售实拍壁纸
    const WP_LIST = ['wp-winter', 'wp-gaming', 'wp-anime', 'wp-doll'];
    const wpRotateToggle = document.getElementById('wallpaperRotateToggle');
    const wpIntervalSelect = document.getElementById('wallpaperIntervalSelect');
    let wpTimer = null;
    function wpRotateOn() { return !!(wpRotateToggle && wpRotateToggle.checked); }
    function wpIntervalMs() {
      const v = parseInt(wpIntervalSelect && wpIntervalSelect.value, 10);
      return Number.isFinite(v) && v >= 5 ? v * 1000 : 10000;
    }
    function wpStop() { if (wpTimer) { clearInterval(wpTimer); wpTimer = null; } }
    function wpCurrent() {
      const cur = loadAppearance().presetBg || '';
      return WP_LIST.indexOf(cur);
    }
    function wpTick() {
      const idx = wpCurrent();
      if (idx === -1) return; // 当前不是实拍壁纸（用户切到渐变/无背景），保持不动
      const next = WP_LIST[(idx + 1) % WP_LIST.length];
      const ap2 = loadAppearance();
      ap2.presetBg = next;
      saveAppearance(ap2);
      crossfadeBg('--preset-bg-fade', () => applyPresetBg(next));
      if (presetBgSelect) presetBgSelect.value = next; // 选择器同步跟随，所见即所得
    }
    function wpSync() {
      wpStop();
      if (!wpRotateOn()) return;
      // 开启轮换但当前不是实拍壁纸：先落到第一张，立即进入轮换节奏
      if (wpCurrent() === -1) {
        const ap2 = loadAppearance();
        ap2.presetBg = WP_LIST[0];
        saveAppearance(ap2);
        crossfadeBg('--preset-bg-fade', () => applyPresetBg(WP_LIST[0]));
        if (presetBgSelect) presetBgSelect.value = WP_LIST[0];
      }
      wpTimer = setInterval(wpTick, wpIntervalMs());
    }
    if (wpRotateToggle) {
      wpRotateToggle.checked = ap.wallpaperRotate === '1';
      wpRotateToggle.addEventListener('change', () => {
        const ap2 = loadAppearance();
        ap2.wallpaperRotate = wpRotateToggle.checked ? '1' : '';
        saveAppearance(ap2);
        wpSync();
      });
    }
    if (wpIntervalSelect) {
      wpIntervalSelect.value = ap.wallpaperInterval || '10';
      wpIntervalSelect.addEventListener('change', () => {
        const ap2 = loadAppearance();
        ap2.wallpaperInterval = wpIntervalSelect.value;
        saveAppearance(ap2);
        wpSync(); // 间隔变化立即按新周期重启计时器
      });
    }
    // 窗口隐藏（最小化/切走）暂停轮换，回来继续——省电且不空转
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) wpStop();
      else wpSync();
    });
    wpSync();
    // 背景模糊度滑块（位于「背景图片」卡内，预设背景/导入图片均可叠加）
    const blurSlider = document.getElementById('bgBlur');
    const blurVal = document.getElementById('bgBlurVal');
    if (blurSlider) {
      blurSlider.value = ap.bgBlur == null ? 0 : ap.bgBlur;
      if (blurVal) blurVal.textContent = blurSlider.value + '%';
      // 编程式赋值不触发 input 事件，手动同步轨道填充（ds.slider）
      window.ds?.slider?.sync?.(blurSlider);
      applyBgBlur(blurSlider.value);
      // 审查 3-3：视觉即时生效，存储防抖 150ms——一次拖动不再产生上百次同步 localStorage 写
      let blurSaveTimer = null;
      blurSlider.addEventListener('input', () => {
        const v = parseInt(blurSlider.value, 10) || 0;
        if (blurVal) blurVal.textContent = v + '%';
        applyBgBlur(v);
        clearTimeout(blurSaveTimer);
        blurSaveTimer = setTimeout(() => {
          const ap2 = migrateSkinToBlur(loadAppearance());
          ap2.bgBlur = v;
          saveAppearance(ap2);
        }, 150);
      });
    }
  }


  // 背景模糊度滑块（Motion.Lab range-drag 适配）：拖动实时模糊壁纸 .layout::before
  function initBgBlur() {
    var range = document.getElementById('bgBlurRange');
    if (!range) return;
    var track = range.querySelector('.bbr-track');
    var fill = range.querySelector('.bbr-fill');
    var knob = range.querySelector('.bbr-knob');
    var valEl = document.getElementById('bgBlurVal');
    var MAX_BLUR = 20;
    var dragging = false;
    var blurSaveTimer = null;
    function setBlur(pct) {
      pct = Math.max(0, Math.min(100, pct));
      var px = (pct / 100 * MAX_BLUR).toFixed(1);
      fill.style.width = pct + '%';
      knob.style.left = pct + '%';
      valEl.textContent = Math.round(pct) + '%';
      document.documentElement.style.setProperty('--bg-blur', px + 'px');
      // v3.5.1 动效审查 M7：原实现每次 mousemove 都同步写一遍全量 appearance，
      // 拖动一次会打出上百次 JSON 序列化 + 同步 IO（阻塞主线程）；改为 150ms 防抖落盘，
      // 与上方另一处滑块（blurSaveTimer 模式）统一。
      clearTimeout(blurSaveTimer);
      blurSaveTimer = setTimeout(function () {
        try {
          var ap = JSON.parse(localStorage.getItem('winclean-appearance') || '{}');
          ap.wallpaperBlur = Math.round(pct);
          localStorage.setItem('winclean-appearance', JSON.stringify(ap));
        } catch (e) {}
      }, 150);
    }
    function updateFromClientX(clientX) {
      var r = track.getBoundingClientRect();
      var pct = (clientX - r.left) / r.width * 100;
      setBlur(pct);
    }
    track.addEventListener('mousedown', function (e) {
      dragging = true;
      range.classList.add('dragging');
      updateFromClientX(e.clientX);
      e.preventDefault();
    });
    window.addEventListener('mousemove', function (e) {
      if (dragging) updateFromClientX(e.clientX);
    });
    window.addEventListener('mouseup', function () {
      if (dragging) { dragging = false; range.classList.remove('dragging'); }
    });
    try {
      var ap2 = JSON.parse(localStorage.getItem('winclean-appearance') || '{}');
      setBlur(typeof ap2.wallpaperBlur === 'number' ? ap2.wallpaperBlur : 0);
    } catch (e) { setBlur(0); }
  }
  function init() {
    if (isInitialized) return;
    isInitialized = true;
    document.getElementById('btnRescanPaths')?.addEventListener('click', openModal);
    document.getElementById('btnOpenModels')?.addEventListener('click', () => {
      if (window.api?.modelsWindow?.open) {
        window.api.modelsWindow.open();
      } else {
        window.app?.toast('warning', '当前环境不支持打开大模型管理窗口');
      }
    });
    document.getElementById('btnOpenFonts')?.addEventListener('click', () => {
      if (window.fontmanager && typeof window.fontmanager.open === 'function') {
        window.fontmanager.open();
      } else {
        window.app?.toast('warning', '当前环境不支持打开字体选择窗口');
      }
    });
    setTimeout(load, 300);
    initAppearance();
    initBgBlur();
  }

  window.pathbinding = { init, load, autoScan, openModal, getConfig: () => pathConfig, GROUPS };
})();
